SIGNABLE_V2_B64 = VIEW_PSBTS[1]
from embit.transaction import SIGHASH, Transaction, TransactionInput, TransactionOutput


def assert_invalid(hex_data):
    """Both parsers must reject the vector with PSBTError."""
    raw = unhexlify(hex_data)
    with pytest.raises(PSBTError):
        PSBT.parse(raw)
    with pytest.raises(PSBTError):
        _exercise_view(raw)


def parse_valid(hex_data):
    """Both parsers must accept the vector, agree, and round-trip it byte for byte."""
    raw = unhexlify(hex_data)
    psbt = PSBT.parse(raw)
    assert psbt.serialize() == raw
    view = _exercise_view(raw)
    assert psbt.version == view.version
    assert len(psbt.inputs) == view.num_inputs
    assert len(psbt.outputs) == view.num_outputs
    assert psbt.tx_version == view.tx_version
    assert psbt.locktime == view.locktime
    try:
        tx = psbt.tx
    except PSBTError:
        # uncomputable locktime: a valid PSBT that no signer can use yet
        with pytest.raises(PSBTError):
            view.determine_locktime()
    else:
        assert tx.serialize() == view_tx(view).serialize()
    out = BytesIO()
    view.write_to(out)
    assert out.getvalue() == raw
    return psbt


def view_tx(view):
    """The unsigned transaction as PSBTView sees it."""
    return Transaction(
        version=view.tx_version,
        vin=[view.vin(i) for i in range(view.num_inputs)],
        vout=[view.vout(i) for i in range(view.num_outputs)],
        locktime=view.determine_locktime(),
    )


