class TestPSBTLocktime:
    """Test locktime determination algorithm for PSBTv2"""

    def test_locktime_no_locktimes_specified(self):
        """No locktimes specified should return 0"""
        hex_data = "70736274ff01020402000000010401010105010201fb040200000000010e200b0ad921419c1c8719735d72dc739f9ea9e0638d1fe4c1eef0f9944084815fc8010f0400000000000103080008af2f000000000104160014c430f64c4756da310dbd1a085572ef299926272c000103088bbdeb0b0000000001041600144dd193ac964a56ac1b9e1cca8454fe2f474f851300"

        psbt = parse_valid(hex_data)
        assert psbt.determine_locktime() == 0

    def test_locktime_fallback_zero(self):
        """Fallback locktime of 0 should return 0"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert psbt.determine_locktime() == 0

    def test_locktime_height_10000(self):
        """Height locktime of 10000 should return 10000"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert psbt.determine_locktime() == 10000

    def test_locktime_max_height(self):
        """Multiple height locktimes should return maximum"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 10000  # max(10000, 9000)

    def test_locktime_height_and_time(self):
        """1 input with Height and other with height and time locktimes should return max height value"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 10000

    def test_locktime_height_preferred_over_time(self):
        """Height locktime should be preferred when both present (BIP-370: height preferred on tie)"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 10000  # Height takes priority over time

    def test_locktime_time_only(self):
        """Time locktime only should return time value"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 1657048460

    def test_locktime_max_time(self):
        """Multiple time locktimes should return maximum"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 1657048460

    def test_locktime_time_wins_when_not_all_support_height(self):
        """Input 1 has height 10000 and time 1657048459, Input 2 has time 1657048460 only should return max time 1657048460"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        assert psbt.determine_locktime() == 1657048460

    def test_locktime_uncomputable(self):
        """Input with height only and input with time only should raise PSBTError"""
        hex_data = ""

        psbt = parse_valid(hex_data)
        assert len(psbt.inputs) == 2
        with pytest.raises(PSBTError):
            psbt.determine_locktime()


class TestPSBTv2Constructor:
    """Test BIP-370 Creator / Constructor role: create_v2(), add_input(), add_output()"""

    def test_create_v2_defaults(self):
        """create_v2() produces a version-2 PSBT with sensible defaults"""
        psbt = PSBT.create_v2()
        assert psbt.version == 2
        assert psbt.tx_version == 2
        assert psbt.locktime is None
        assert psbt.tx_modifiable_flags == TxModifiable.INPUTS | TxModifiable.OUTPUTS
        assert len(psbt.inputs) == 0
        assert len(psbt.outputs) == 0

    def test_create_v2_custom_params(self):
        """create_v2() accepts custom tx_version, fallback_locktime and tx_modifiable"""
        psbt = PSBT.create_v2(
            tx_version=1,
            fallback_locktime=600000,
            tx_modifiable=TxModifiable.INPUTS,
        )
        assert psbt.tx_version == 1
        assert psbt.locktime == 600000
        assert psbt.tx_modifiable_flags == TxModifiable.INPUTS

    def test_add_input_appends_and_updates_count(self):
        """add_input() appends the scope and increments the global input count"""
        psbt = PSBT.create_v2()
        inp = InputScope()
        inp.txid = bytes(32)
        inp.vout = 0
        psbt.add_input(inp)
        assert len(psbt.inputs) == 1
        assert psbt._raw_input_count_from_global == 1

    def test_add_input_requires_inputs_modifiable(self):
        """add_input() raises when INPUTS bit is clear"""
        psbt = PSBT.create_v2(tx_modifiable=TxModifiable.OUTPUTS)
        inp = InputScope()
        inp.txid = bytes(32)
        inp.vout = 0
        with pytest.raises(PSBTError):
            psbt.add_input(inp)

    def test_add_input_requires_txid(self):
        """add_input() raises when PSBT_IN_PREVIOUS_TXID is absent"""
        psbt = PSBT.create_v2()
        inp = InputScope()
        inp.vout = 0
        with pytest.raises(PSBTError):
            psbt.add_input(inp)

    def test_add_input_requires_vout(self):
        """add_input() raises when PSBT_IN_OUTPUT_INDEX is absent"""
        psbt = PSBT.create_v2()
        inp = InputScope()
        inp.txid = bytes(32)
        with pytest.raises(PSBTError):
            psbt.add_input(inp)

    def test_add_output_appends_and_updates_count(self):
        """add_output() appends the scope and increments the global output count"""
        psbt = PSBT.create_v2()
        out = OutputScope()
        out.value = 100000
        out.script_pubkey = Script(b"\x00\x14" + bytes(20))
        psbt.add_output(out)
        assert len(psbt.outputs) == 1
        assert psbt._raw_output_count_from_global == 1

    def test_add_output_requires_outputs_modifiable(self):
        """add_output() raises when OUTPUTS bit is clear"""
        psbt = PSBT.create_v2(tx_modifiable=TxModifiable.INPUTS)
        out = OutputScope()
        out.value = 100000
        out.script_pubkey = Script(b"\x00\x14" + bytes(20))
        with pytest.raises(PSBTError):
            psbt.add_output(out)

    def test_add_output_requires_amount(self):
        """add_output() raises when PSBT_OUT_AMOUNT is absent"""
        psbt = PSBT.create_v2()
        out = OutputScope()
        out.script_pubkey = Script(b"\x00\x14" + bytes(20))
        with pytest.raises(PSBTError):
            psbt.add_output(out)

    def test_add_output_requires_script(self):
        """add_output() raises when PSBT_OUT_SCRIPT is absent"""
        psbt = PSBT.create_v2()
        out = OutputScope()
        out.value = 100000
        with pytest.raises(PSBTError):
            psbt.add_output(out)


class TestTxModifiableUpdate:
    """Test BIP-370 Signer role: _update_tx_modifiable() correctly restricts future modifications"""

    def test_sighash_all_clears_inputs_and_outputs(self):
        """SIGHASH_ALL (not ANYONECANPAY) must clear both INPUTS and OUTPUTS bits"""
        psbt = PSBT.create_v2()
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        psbt._update_tx_modifiable(SIGHASH.ALL)
        assert not psbt.is_inputs_modifiable()
        assert not psbt.is_outputs_modifiable()
        assert not psbt.has_sighash_single()

    def test_sighash_none_clears_inputs_preserves_outputs(self):
        """SIGHASH_NONE clears INPUTS bit but must not touch the OUTPUTS bit"""
        psbt = PSBT.create_v2()
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        psbt._update_tx_modifiable(SIGHASH.NONE)
        assert not psbt.is_inputs_modifiable()
        assert psbt.is_outputs_modifiable()

    def test_sighash_single_sets_flag_and_clears_inputs(self):
        """SIGHASH_SINGLE sets SIGHASH_SINGLE flag and clears INPUTS and OUTPUTS bits"""
        psbt = PSBT.create_v2()
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        psbt._update_tx_modifiable(SIGHASH.SINGLE)
        assert not psbt.is_inputs_modifiable()
        assert not psbt.is_outputs_modifiable()
        assert psbt.has_sighash_single()

    def test_sighash_all_anyonecanpay_preserves_inputs_clears_outputs(self):
        """SIGHASH_ALL|ANYONECANPAY preserves INPUTS bit and clears OUTPUTS bit"""
        psbt = PSBT.create_v2()
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        psbt._update_tx_modifiable(SIGHASH.ALL | SIGHASH.ANYONECANPAY)
        assert psbt.is_inputs_modifiable()
        assert not psbt.is_outputs_modifiable()

    def test_update_creates_flags_when_absent(self):
        """_update_tx_modifiable initialises the field to 0 when it was absent"""
        psbt = PSBT.create_v2()
        psbt.tx_modifiable_flags = None
        psbt._update_tx_modifiable(SIGHASH.ALL)
        assert psbt.tx_modifiable_flags == 0

    def test_no_op_for_psbtv0(self):
        """_update_tx_modifiable is a no-op for PSBTv0 (PSBT_GLOBAL_TX_MODIFIABLE is v2-only)"""
        psbt = PSBT.create_v2()
        psbt.version = None  # downgrade to v0
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        psbt._update_tx_modifiable(SIGHASH.ALL)
        # must remain untouched because version != 2
        assert psbt.tx_modifiable_flags == TxModifiable.INPUTS | TxModifiable.OUTPUTS


class TestPSBTViewV2Validation:
    def test_psbtview_rejects_v2_only_global_in_v0(self):
        """PSBTView should enforce the same v0/v2 global separation as PSBT"""
        psbt = PSBT(Transaction())
        raw = psbt.serialize()
        stream = BytesIO(raw)
        stream.read(len(PSBT.MAGIC))
        while True:
            pos = stream.tell()
            key_len = stream.read(1)[0]
            if key_len == 0:
                separator = pos
                break
            stream.seek(key_len, 1)
            value_len = stream.read(1)[0]
            stream.seek(value_len, 1)

        tx_version_kv = b"\x01\x02\x04\x02\x00\x00\x00"
        invalid = raw[:separator] + tx_version_kv + raw[separator:]
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(invalid))


class TestPSBTv2TransactionVersion:
    def test_psbt_tx_preserves_zero_and_high_bit_versions(self):
        """PSBT_GLOBAL_TX_VERSION is copied through verbatim, zero must not fall back to 2"""
        psbt = PSBT.create_v2(tx_version=0)
        inp = InputScope()
        inp.txid = bytes(32)
        inp.vout = 0
        psbt.add_input(inp)
        out = OutputScope()
        out.value = 1
        out.script_pubkey = Script(b"")
        psbt.add_output(out)
        assert psbt.tx.serialize()[:4] == b"\x00\x00\x00\x00"

        psbt.tx_version = 0xFFFFFFFF
        assert psbt.tx.serialize()[:4] == b"\xff\xff\xff\xff"


class TestPSBTv2Compression:
    def test_psbtv2_compress_non_witness_utxo_is_key_order_independent(self):
        """PSBTv2 compress should not load the full prev tx when 0x00 precedes 0x0f"""
        prev = Transaction(
            vin=[TransactionInput(bytes([1]) * 32, 0)],
            vout=[TransactionOutput(1234, Script(b"\x51"))],
        )
        psbt = PSBT.create_v2()
        inp = InputScope()
        inp.txid = prev.txid()
        inp.vout = 0
        # InputScope serializes non_witness_utxo before PSBTv2 prevout fields.
        inp.non_witness_utxo = prev
        psbt.add_input(inp)
        out = OutputScope()
        out.value = 1000
        out.script_pubkey = Script(b"\x51")
        psbt.add_output(out)

        parsed = PSBT.parse(psbt.serialize(), compress=CompressMode.PARTIAL)
        assert parsed.inputs[0].non_witness_utxo is None
        assert parsed.inputs[0]._utxo.value == 1234
        assert parsed.verify()


def kv(key, value):
    return compact.to_bytes(len(key)) + key + compact.to_bytes(len(value)) + value


TXID_A = bytes(range(32))
TXID_B = bytes(range(0x20, 0x40))
V2_IN = kv(b"\x0e", TXID_A) + kv(b"\x0f", (0).to_bytes(4, "little"))
V2_OUT = kv(b"\x03", (1000).to_bytes(8, "little")) + kv(b"\x04", b"\x51")


def raw_v2(inputs, outputs, extra_globals=b""):
    """A raw PSBTv2 from already serialized input and output maps (no separators)."""
    g = (
        kv(b"\x02", (2).to_bytes(4, "little"))
        + kv(b"\x04", compact.to_bytes(len(inputs)))
        + kv(b"\x05", compact.to_bytes(len(outputs)))
        + extra_globals
        + kv(b"\xfb", (2).to_bytes(4, "little"))
    )
    return (
        PSBT.MAGIC
        + g
        + b"\x00"
        + b"".join(m + b"\x00" for m in inputs)
        + b"".join(m + b"\x00" for m in outputs)
    )


class TestPSBTViewV2ScopeFields:
    """PSBTView must reject the same malformed v2 scope fields as PSBT"""

    def test_baseline_valid(self):
        raw = raw_v2([V2_IN], [V2_OUT])
        psbt = PSBT.parse(raw)
        view = PSBTView.view(BytesIO(raw))
        assert view.vin(0).serialize() == psbt.inputs[0].vin.serialize()
        assert view.vout(0).serialize() == psbt.outputs[0].vout.serialize()

    @pytest.mark.parametrize(
        "bogus_in, bogus_out",
        [
            (kv(b"\x0e\xaa", TXID_B), b""),
            (kv(b"\x0f\xaa", (7).to_bytes(4, "little")), b""),
            (kv(b"\x10\xaa", (7).to_bytes(4, "little")), b""),
            (b"", kv(b"\x03\xaa", (999999).to_bytes(8, "little"))),
            (b"", kv(b"\x04\xaa", b"\x52")),
        ],
    )
    def test_keyed_variants_of_keyless_fields_rejected(self, bogus_in, bogus_out):
        # the bogus key precedes the real one so a prefix match would pick it up
        raw = raw_v2([bogus_in + V2_IN], [bogus_out + V2_OUT])
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        view = PSBTView.view(BytesIO(raw))
        with pytest.raises(PSBTError):
            view.vin(0)
            view.vout(0)
        with pytest.raises(PSBTError):
            view.input(0)
            view.output(0)

    def test_duplicate_prevout_fields_rejected(self):
        raw = raw_v2([kv(b"\x0e", TXID_B) + V2_IN], [V2_OUT])
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw)).vin(0)
        raw = raw_v2([V2_IN], [kv(b"\x03", bytes(8)) + V2_OUT])
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw)).vout(0)

    def test_input_and_output_validate_required_fields(self):
        raw = raw_v2([kv(b"\x0f", bytes(4))], [V2_OUT])
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw)).input(0)
        raw = raw_v2([V2_IN], [kv(b"\x04", b"\x51")])
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw)).output(0)

    def test_sign_does_not_emit_sigs_before_rejecting_a_later_input(self):
        """A malformed input 1 must be caught while hashing input 0, not after."""
        psbt = PSBT.from_string(SIGNABLE_V2_B64)
        raw_inputs = [inp.serialize(version=2)[:-1] for inp in psbt.inputs]
        raw_outputs = [out.serialize(version=2)[:-1] for out in psbt.outputs]
        raw_inputs[1] = kv(b"\x0e\xaa", TXID_B) + raw_inputs[1]
        raw = raw_v2(raw_inputs, raw_outputs)
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        view = PSBTView.view(BytesIO(raw))
        sigs = BytesIO()
        with pytest.raises(PSBTError):
            view.sign_with(SIGNING_ROOT, sigs)
        assert sigs.getvalue() == b""


def _exercise_view(raw, compress=CompressMode.KEEP_ALL):
    """Parses with PSBTView and touches every lazily-read field."""
    view = PSBTView.view(BytesIO(raw), compress=compress)
    view.tx_version
    view.locktime
    for i in range(view.num_inputs):
        view.input(i)
        view.vin(i)
    for i in range(view.num_outputs):
        view.output(i)
        view.vout(i)
    view.write_to(BytesIO())
    return view


class TestPSBTErrorHygiene:
    """Malformed input must surface as PSBTError from every parse path"""

    V2_UPDATED = unhexlify(
        ""
    )
    SAMPLES = [V2_UPDATED, a2b_base64(VIEW_PSBTS[0]), a2b_base64(VIEW_PSBTS[1])]

    @pytest.mark.parametrize("compress", [CompressMode.KEEP_ALL, CompressMode.PARTIAL])
    def test_truncated_input(self, compress):
        for raw in self.SAMPLES:
            for n in range(len(raw)):
                with pytest.raises(PSBTError):
                    PSBT.parse(raw[:n], compress=compress)
                with pytest.raises(PSBTError):
                    PSBTView.view(BytesIO(raw[:n]), compress=compress)

    @pytest.mark.parametrize("compress", [CompressMode.KEEP_ALL, CompressMode.PARTIAL])
    def test_corrupted_byte(self, compress):
        for raw in self.SAMPLES:
            # every byte of the small vector, every third of the larger ones
            for n in range(0, len(raw), 1 if len(raw) < 600 else 3):
                flipped = raw[:n] + bytes([raw[n] ^ 0xFF]) + raw[n + 1 :]
                try:
                    PSBT.parse(flipped, compress=compress)
                except PSBTError:
                    pass
                try:
                    _exercise_view(flipped, compress=compress)
                except PSBTError:
                    pass

    @pytest.mark.parametrize("separator", [b"\xfd\x00\x00", b"\xfd", b"\xfe\x00\x00"])
    def test_non_canonical_or_truncated_separator(self, separator):
        raw = raw_v2([V2_IN], [V2_OUT])
        assert raw.endswith(b"\x00")
        raw = raw[:-1] + separator
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        with pytest.raises(PSBTError):
            _exercise_view(raw)

    def test_compact_rejects_non_canonical_and_truncated(self):
        with pytest.raises(ValueError):
            compact.from_bytes(b"\xfd\x00\x00")
        with pytest.raises(ValueError):
            compact.from_bytes(b"\xfe\xff\xff\x00\x00")
        with pytest.raises(RuntimeError):
            compact.from_bytes(b"\xfd\x00")
        assert compact.from_bytes(b"\xfd\xfd\x00") == 0xFD
        assert compact.from_bytes(b"\xfe\x00\x00\x01\x00") == 0x10000

    def test_malformed_xpub_global(self):
        raw = raw_v2([V2_IN], [V2_OUT], extra_globals=kv(b"\x01\x00", bytes(4)))
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        with pytest.raises(PSBTError):
            _exercise_view(raw)
        # right length, garbage content
        raw = raw_v2([V2_IN], [V2_OUT], extra_globals=kv(b"\x01" + bytes(78), bytes(4)))
        with pytest.raises(PSBTError):
            PSBT.parse(raw)

    def test_corrupted_global_transaction(self):
        raw = a2b_base64(VIEW_PSBTS[0])
        # global tx value starts right after magic + key(00) + value length
        assert raw[5:7] == b"\x01\x00"
        tx_len_size = len(compact.to_bytes(len(raw)))  # >= 1
        corrupt = raw[: 7 + tx_len_size + 4] + b"\xff" * 8 + raw[7 + tx_len_size + 12 :]
        with pytest.raises(PSBTError):
            PSBT.parse(corrupt)
        with pytest.raises(PSBTError):
            _exercise_view(corrupt)

    @pytest.mark.parametrize("trailing", [b"\x00", b"\xff", V2_OUT + b"\x00"])
    def test_rejects_trailing_bytes(self, trailing):
        raw = raw_v2([V2_IN], [V2_OUT])
        with pytest.raises(PSBTError):
            PSBT.parse(raw + trailing)
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw + trailing))
        raw = a2b_base64(VIEW_PSBTS[0])
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw + trailing))

    def test_view_rejects_count_larger_than_maps(self):
        raw = raw_v2([V2_IN, V2_IN], [V2_OUT])
        assert raw[raw.index(b"\x01\x04\x01") + 3] == 2
        raw = raw.replace(b"\x01\x04\x01\x02", b"\x01\x04\x01\x03", 1)
        with pytest.raises(PSBTError):
            PSBT.parse(raw)
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw))

    def test_corrupted_nested_value_reports_key(self):
        # bip32 derivation with a 1-byte pubkey in the key
        raw = raw_v2([V2_IN + kv(b"\x06\x02", bytes(8))], [V2_OUT])
        with pytest.raises(PSBTError, match="0602"):
            PSBT.parse(raw)
        with pytest.raises(PSBTError):
            _exercise_view(raw)

    def test_bad_global_count_in_constructor(self):
        with pytest.raises(PSBTError):
            PSBT(unknown={b"\x04": b"\xfd"}, version=2)

    def test_serialize_rejects_out_of_range_fields(self):
        def v2():
            psbt = PSBT.create_v2()
            inp = InputScope()
            inp.txid = bytes(32)
            inp.vout = 0
            psbt.add_input(inp)
            out = OutputScope()
            out.value = 1
            out.script_pubkey = Script(b"\x51")
            psbt.add_output(out)
            return psbt

        psbt = v2()
        psbt.serialize()
        for attr, value in [
            ("tx_modifiable_flags", 300),
            ("locktime", 2**32),
            ("tx_version", -1),
        ]:
            psbt = v2()
            setattr(psbt, attr, value)
            with pytest.raises(PSBTError):
                psbt.serialize()
        for attr, value in [
            ("sequence", -1),
            ("vout", 2**32),
            ("required_height_locktime", 2**40),
            ("txid", bytes(31)),
        ]:
            psbt = v2()
            setattr(psbt.inputs[0], attr, value)
            with pytest.raises(PSBTError):
                psbt.serialize()
        psbt = v2()
        psbt.outputs[0].value = 2**63
        with pytest.raises(PSBTError):
            psbt.serialize()


def to_v2(psbt):
    """Rebuilds a parsed PSBTv0 as an equivalent PSBTv2."""
    v2 = PSBT.create_v2(tx_version=psbt.tx.version, fallback_locktime=psbt.locktime)
    for inp in psbt.inputs:
        v2.add_input(inp)
    for out in psbt.outputs:
        v2.add_output(out)
    v2.tx_modifiable_flags = None
    return PSBT.parse(v2.serialize())


def sign_both(raw, root, sighash=SIGHASH.DEFAULT, compress=CompressMode.KEEP_ALL):
    """Signs raw with PSBT and PSBTView, returns (psbt, view, psbt bytes, view bytes)."""
    psbt = PSBT.parse(raw, compress=compress)
    view = PSBTView.view(BytesIO(raw), compress=compress)
    n1 = psbt.sign_with(root, sighash)
    sigs = BytesIO()
    n2 = view.sign_with(root, sigs, sighash)
    assert n1 == n2
    sigs.seek(0)
    out = BytesIO()
    # write_to() applies the view's compress mode to every scope
    view.write_to(out, extra_input_streams=[sigs])
    for sc in psbt.inputs + psbt.outputs:
        sc.clear_metadata(compress=compress)
    return psbt, view, psbt.serialize(), out.getvalue()


class TestPSBTViewParity:
    """PSBT and PSBTView expose the same values and produce the same bytes"""

    LOCKTIME_VECTORS = [
        # (hex, fallback field, determined locktime)
        (
            "",
            0,
            10000,
        ),
        (
            "70736274ff01020402000000010401010105010201fb040200000000010e200b0ad921419c1c8719735d72dc739f9ea9e0638d1fe4c1eef0f9944084815fc8010f0400000000000103080008af2f000000000104160014c430f64c4756da310dbd1a085572ef299926272c000103088bbdeb0b0000000001041600144dd193ac964a56ac1b9e1cca8454fe2f474f851300",
            None,
            0,
        ),
    ]

    @pytest.mark.parametrize("hex_data, fallback, determined", LOCKTIME_VECTORS)
    def test_locktime_api(self, hex_data, fallback, determined):
        raw = unhexlify(hex_data)
        psbt = PSBT.parse(raw)
        view = PSBTView.view(BytesIO(raw))
        assert psbt.locktime == view.locktime == fallback
        assert psbt.determine_locktime() == view.determine_locktime() == determined
        assert psbt.tx.locktime == determined
        # v0: both are the global tx locktime
        raw = a2b_base64(VIEW_PSBTS[0])
        psbt = PSBT.parse(raw)
        view = PSBTView.view(BytesIO(raw))
        assert psbt.locktime == view.locktime == psbt.tx.locktime
        assert psbt.determine_locktime() == view.determine_locktime() == psbt.locktime

    def test_unknown_and_xpub_globals_keep_order(self):
        xpub = SIGNING_ROOT.to_public().serialize()
        extra = (
            kv(b"\xf0", b"first")
            + kv(b"\x01" + xpub, SIGNING_ROOT.my_fingerprint + bytes(4))
            + kv(b"\x07", b"second")
        )
        raw = raw_v2([V2_IN], [V2_OUT], extra_globals=extra)
        psbt = PSBT.parse(raw)
        assert list(psbt.unknown) == [b"\xf0", b"\x07"]
        assert len(psbt.xpubs) == 1
        out = BytesIO()
        PSBTView.view(BytesIO(raw)).write_to(out)
        assert psbt.serialize() == out.getvalue()
        # PSBT and PSBTView agree even when the source order differs from theirs
        assert PSBT.parse(out.getvalue()).serialize() == out.getvalue()

    def test_scope_constructor_accepts_v2_unknowns(self):
        txid = bytes(range(32))
        inp = InputScope(
            {b"\x0e": txid[::-1], b"\x0f": (3).to_bytes(4, "little")}, version=2
        )
        assert inp.txid == txid and inp.vout == 3 and inp.unknown == {}
        with pytest.raises(PSBTError):
            InputScope({b"\x0e": txid[::-1]})
        out = OutputScope({b"\x03": (5).to_bytes(8, "little")}, version=2)
        assert out.value == 5
        with pytest.raises(PSBTError):
            OutputScope({b"\x03": (5).to_bytes(8, "little")})

    @pytest.mark.parametrize("compress", [CompressMode.KEEP_ALL, CompressMode.PARTIAL])
    def test_taproot_keypath_signing_matches(self, compress):
        from .test_taproot import TAP_PSBTS, KEY_A

        for raw in [
            a2b_base64(TAP_PSBTS[0]),
            to_v2(PSBT.from_string(TAP_PSBTS[0])).serialize(),
        ]:
            psbt, view, ser1, ser2 = sign_both(raw, KEY_A, compress=compress)
            assert psbt.inputs[0].taproot_key_sig is not None
            assert ser1 == ser2
            if psbt.version == 2:
                assert psbt.tx_modifiable_flags == view.tx_modifiable_flags == 0

    def test_taproot_scriptpath_signing_matches(self):
        from .test_taproot import TAPTREE_PSBT, TAPTREE_KEYS

        for raw in [
            a2b_base64(TAPTREE_PSBT),
            to_v2(PSBT.from_string(TAPTREE_PSBT)).serialize(),
        ]:
            psbt = PSBT.parse(raw)
            view = PSBTView.view(BytesIO(raw))
            sigs = BytesIO()
            for key in TAPTREE_KEYS:
                assert psbt.sign_with(key) == view.sign_with(key, sigs)
            # one scope per key per input in the stream; merge them all
            sigs.seek(0)
            out = BytesIO()
            streams = [BytesIO(sigs.getvalue()) for _ in TAPTREE_KEYS]
            # each stream must be positioned at its own signing pass
            for n, s in enumerate(streams):
                for _ in range(n * view.num_inputs):
                    InputScope.read_from(s, version=view.version)
            view.write_to(out, extra_input_streams=streams)
            assert psbt.serialize() == out.getvalue()

    def test_missing_utxo_is_psbterror(self):
        raw = a2b_base64(VIEW_PSBTS[1])
        psbt = PSBT.parse(raw)
        psbt.inputs[1].witness_utxo = None
        psbt.inputs[1].non_witness_utxo = None
        raw = psbt.serialize()
        assert not psbt.inputs[1].is_taproot
        with pytest.raises(PSBTError):
            PSBT.parse(raw).sign_with(SIGNING_ROOT)
        with pytest.raises(PSBTError):
            PSBTView.view(BytesIO(raw)).sign_with(SIGNING_ROOT, BytesIO())
        with pytest.raises(PSBTError):
            PSBT.parse(raw).fee()


class TestNonWitnessUtxoLength:
    """The declared PSBT_IN_NON_WITNESS_UTXO length must match the transaction"""

    @pytest.mark.parametrize("delta", [-2, -1, 1, 2, 40])
    @pytest.mark.parametrize("compress", [CompressMode.KEEP_ALL, CompressMode.PARTIAL])
    def test_length_mismatch_rejected(self, delta, compress):
        for b64 in [VIEW_PSBTS[0], VIEW_PSBTS[1]]:
            psbt = PSBT.from_string(b64)
            tx = psbt.inputs[0].non_witness_utxo.serialize()
            raw = psbt.serialize()
            good = kv(b"\x00", tx)
            assert raw.count(good) == 1
            bad = compact.to_bytes(len(tx) + delta) + tx
            if delta > 0:
                # pad so the value itself is still present, the framing is off
                bad += b"\x00" * delta
            raw = raw.replace(good, b"\x01" + bad, 1)
            with pytest.raises(PSBTError):
                PSBT.parse(raw, compress=compress)
            # the shifted framing is caught by the scope walk in view() or,
            # when the framing happens to line up, by the value parse
            with pytest.raises(PSBTError):
                view = PSBTView.view(BytesIO(raw), compress=compress)
                view.input(0)
                view.vin(0)
                view.sighash(0)


class TestTxModifiableAfterSigning:
    """PSBT_GLOBAL_TX_MODIFIABLE after a real sign_with, in PSBT and PSBTView"""

    @pytest.mark.parametrize(
        "sighash, expected",
        [
            (SIGHASH.ALL, 0),
            (SIGHASH.ALL | SIGHASH.ANYONECANPAY, TxModifiable.INPUTS),
            (SIGHASH.NONE, TxModifiable.OUTPUTS),
            (
                SIGHASH.NONE | SIGHASH.ANYONECANPAY,
                TxModifiable.INPUTS | TxModifiable.OUTPUTS,
            ),
            (SIGHASH.SINGLE, TxModifiable.SIGHASH_SINGLE),
            (
                SIGHASH.SINGLE | SIGHASH.ANYONECANPAY,
                TxModifiable.INPUTS | TxModifiable.SIGHASH_SINGLE,
            ),
        ],
    )
    def test_flags_after_signing(self, sighash, expected):
        psbt = PSBT.from_string(SIGNABLE_V2_B64)
        psbt.tx_modifiable_flags = TxModifiable.INPUTS | TxModifiable.OUTPUTS
        raw = psbt.serialize()
        psbt, view, ser1, ser2 = sign_both(raw, SIGNING_ROOT, sighash)
        assert psbt.tx_modifiable_flags == expected
        assert view.tx_modifiable_flags == expected
        assert PSBT.parse(ser2).tx_modifiable_flags == expected
        assert ser1 == ser2

    def test_absent_field_is_set_by_signer(self):
        psbt, view, ser1, ser2 = sign_both(a2b_base64(SIGNABLE_V2_B64), SIGNING_ROOT)
        assert psbt.tx_modifiable_flags == view.tx_modifiable_flags == 0
        assert ser1 == ser2

    def test_untouched_when_nothing_signed(self):
        psbt = PSBT.from_string(SIGNABLE_V2_B64)
        raw = psbt.serialize()
        other = SIGNING_ROOT.derive([1])
        psbt, view, ser1, ser2 = sign_both(raw, other)
        assert psbt.tx_modifiable_flags is None
        assert view.tx_modifiable_flags is None
        assert ser1 == ser2 == raw

    def test_v0_never_gets_the_field(self):
        raw = a2b_base64(VIEW_PSBTS[0])
        psbt, view, ser1, ser2 = sign_both(raw, SIGNING_ROOT)
        assert psbt.tx_modifiable_flags is None
        assert view.tx_modifiable_flags is None
        assert ser1 == ser2


class TestPSBTv2Signing:
    """Legacy, segwit and taproot inputs sign the same in v0 and v2"""

    @pytest.mark.parametrize("compress", [CompressMode.KEEP_ALL, CompressMode.PARTIAL])
    def test_legacy_and_segwit(self, compress):
        from .test_psbt import SIGN_PSBT_HEX, SIGN_XKEY
        from embit.bip32 import HDKey

        xkey = HDKey.from_base58(SIGN_XKEY)
        v0 = PSBT.parse(unhexlify(SIGN_PSBT_HEX))
        raw2 = to_v2(v0).serialize()
        v0.sign_with(xkey)
        assert all(inp.partial_sigs for inp in v0.inputs)
        psbt, view, ser1, ser2 = sign_both(raw2, xkey, compress=compress)
        assert ser1 == ser2
        for a, b in zip(v0.inputs, psbt.inputs):
            assert a.partial_sigs == b.partial_sigs
        # the finalized transaction is the same one
        assert psbt.tx.txid() == v0.tx.txid()

    def test_v2_sighash_uses_derived_locktime(self):
        v0 = PSBT.from_string(SIGNABLE_V2_B64)
        v0.inputs[0].required_height_locktime = 200
        raw = v0.serialize()
        psbt, view, ser1, ser2 = sign_both(raw, SIGNING_ROOT)
        assert ser1 == ser2
        assert psbt.tx.locktime == 200
        # signing a copy with the locktime baked into the fallback field and
        # no per-input requirement yields the same signatures
        v0 = PSBT.from_string(SIGNABLE_V2_B64)
        v0.locktime = 200
        v0.sign_with(SIGNING_ROOT)
        for a, b in zip(v0.inputs, psbt.inputs):
            assert a.partial_sigs == b.partial_sigs
